-- EXPERIMENT ONLY: fixture DDL, not proposed production schema or Laravel migration.
-- statement
CREATE TABLE gw_scopes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,currency_code VARCHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,UNIQUE(company_id,branch_id,account_id,currency_code),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE RESTRICT, CHECK(BINARY currency_code=BINARY 'SAR')) ENGINE=InnoDB;
-- statement
CREATE TABLE gw_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,operation VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_key VARBINARY(80) NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,result LONGTEXT NULL,UNIQUE(company_id,operation,request_key)) ENGINE=InnoDB;
-- statement
CREATE TABLE gw_origins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope_id BIGINT UNSIGNED NOT NULL,request_id BIGINT UNSIGNED NOT NULL UNIQUE,shipment_cost_id BIGINT UNSIGNED NOT NULL UNIQUE,journal_entry_id BIGINT UNSIGNED NOT NULL UNIQUE,line_id BIGINT UNSIGNED NOT NULL UNIQUE,driver_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(15,3) NOT NULL CHECK(amount>0),FOREIGN KEY(scope_id) REFERENCES gw_scopes(id) ON DELETE RESTRICT,FOREIGN KEY(request_id) REFERENCES gw_requests(id) ON DELETE RESTRICT,FOREIGN KEY(shipment_cost_id) REFERENCES shipment_costs(id) ON DELETE RESTRICT,FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT,FOREIGN KEY(line_id) REFERENCES journal_entry_lines(id) ON DELETE RESTRICT) ENGINE=InnoDB;
-- statement
CREATE TABLE gw_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,origin_id BIGINT UNSIGNED NOT NULL,request_id BIGINT UNSIGNED NOT NULL UNIQUE,voucher_id BIGINT UNSIGNED NOT NULL UNIQUE,journal_id BIGINT UNSIGNED NOT NULL UNIQUE,amount DECIMAL(15,3) NOT NULL CHECK(amount>0),FOREIGN KEY(origin_id) REFERENCES gw_origins(id) ON DELETE RESTRICT,FOREIGN KEY(request_id) REFERENCES gw_requests(id) ON DELETE RESTRICT,FOREIGN KEY(voucher_id) REFERENCES vouchers(id) ON DELETE RESTRICT,FOREIGN KEY(journal_id) REFERENCES journal_entries(id) ON DELETE RESTRICT) ENGINE=InnoDB;
-- statement
CREATE TABLE gw_exceptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope_id BIGINT UNSIGNED NOT NULL,journal_id BIGINT UNSIGNED NOT NULL UNIQUE,FOREIGN KEY(scope_id) REFERENCES gw_scopes(id) ON DELETE RESTRICT,FOREIGN KEY(journal_id) REFERENCES journal_entries(id) ON DELETE RESTRICT) ENGINE=InnoDB;
